-- GENERATED by `wfj generate` from data/gossip/gossip-30.jsonl. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("gossip", {
  ["3002177b15742961"] = { "Ben fatto. Affidami l'orso, così che possa applicare l'incantesimo curativo.", "." },
  ["300527556dcecfdf"] = { "Ecco, così dovrebbe andare...", "." },
  ["300cb9ec97d156d4"] = { "Perché andiamo da questa parte?", "." },
  ["300e6de1fa9c8669"] = { "Chi osa rubare la mia preziosa cavalcatura? Pagherai per la tua insolenza, mortale!", "." },
  ["300efbc6080a2a54"] = { "Ora sei tu a comandare! Lunga vita al nuovo re dei Gordok!", "." },
  ["3013b7a923a304ac"] = { "%s va su tutte le furie!", "." },
  ["301772277717da56"] = { "Allora, <ispettore/ispettrice> apprendista {name}, il vecchio Pestlezugg ha pronto quel rapporto?", "." },
  ["3021d6081df41e2d"] = { "La ⟦Valley of Trials=Valle delle Sfide⟧ temprerà anche i più deboli fino a farne guerrieri degni di unirsi all'⟦Horde=Orda⟧. Chi non saprà superare le sue prove sarà lasciato a cuocere sotto il sole cocente del deserto.", "." },
  ["3023e2c8cc134c7c"] = { "%s si tira su per il naso un granello di polvere dei sogni...", "." },
  ["302845bad1443036"] = { "Hai sentito, <viaggiatore/viaggiatrice>. Parlami di nuovo quando sarai <pronto/pronta> a parlare con Belgrum.", "." },
  ["302a471a69278d06"] = { "Una scoperta rara, davvero.\n\n<Mathredis annuisce.>\n\nSe vuoi continuare, mi serviranno i componenti.", "." },
  ["302fd6585f4451d9"] = { "E va bene. Visto che non hai comprato tutta la mia merce, non ho altra scelta che guadagnarmi da vivere nella città dei tuoi nemici.", "." },
  ["3032a220e3ad8aa7"] = { "Krathok, un tempo forgiavo armi e voglio riprendere in mano il martello! Insegnami la via del Fabbro d'Armi.", "." },
  ["303d743a4ec17282"] = { "Zamja può aiutarti, {race}?", "." },
  ["303e372e72d9aebc"] = { "Uccideteli tutti. Lasciate i loro gusci al padrone, che li divori...", "." },
  ["303e418a05407d37"] = { "Il ⟦Frostwolf Quartermaster=Quartiermastro dei Lupi Bianchi⟧ si trova a sud-ovest di questo fortilizio. Entra nel fortilizio ed esci sulla destra: vedrai il quartiermastro poco più avanti lungo il sentiero.", "." },
  ["303ee1b50826d1b5"] = { "Le protezioni magiche in quel punto dovrebbero essere abbastanza sostenute dal flusso di energia da contenere l'entità.", "." },
  ["30445edb450ab5f4"] = { "Va bene, va bene. Comunque, diciamo che ho cercato riparo nell'ombra.\n\nLa cosa non è piaciuta granché a Windsor, visto che era già di pessimo umore. Beh, ha cominciato a far roteare il vecchio Ironfoe e a urlare come un pazzo contro gli orchi.", "." },
  ["3044756cbd272b21"] = { "La Dama Oscura ha lanciato la sfida. Sta a noi raccoglierla.", "." },
  ["30486c52b2056f4d"] = { "Oh, sia lode! La tua vigilanza tiene Myzrael nelle profondità della terra!", "." },
  ["304a399f1ba55eaa"] = { "Così impari a lasciar perdere l'erba, {race}.", "." },
  ["304b6afec037d7cd"] = { "Credo che tu abbia sbagliato lavoro, <iniziato/iniziata>. A Kel'Thuzad non servono fioraie...", "." },
  ["304b782422c2d7b4"] = { "Mi serve una fiala di Quintessenza Acquea, Idraxis, perché vado al ⟦Molten Core=Nucleo Ardente⟧ a spegnere una runa dei Signori del Fuoco.", "." },
  ["304ff384d01be6d7"] = { "Abbiamo abbastanza provviste! Il nostro capitano ha ripreso posizione nel ⟦Field of Strife=Pian della Discordia⟧!", "." },
  ["30570c5700a68bd3"] = { "Ho finito, <fratello/sorella>. Finisci tu. Io me ne torno a riposare sulla roccia.", "." },
  ["305c0adcfe46e30d"] = { "L'anziano Venargento si trova vicino a Thelsamar, a Loch Modan.", "." },
  ["305c9aaf4a310e23"] = { "%s esplode, illuminando il cielo con uno splendido spettacolo di fuochi d'artificio! Sembra che ti stia chiamando, <ladro/ladra>.", "." },
  ["3060fa3df14a5928"] = { "Era ora che mi facessi il mio giro.", "." },
  ["30677153be5b3e04"] = { "Il ⟦Stonehearth Graveyard=Cimitero di Cordipietra⟧ è stato preso dall'⟦Horde=Orda⟧!", "." },
  ["306a18e99cf65382"] = { "Uccidete gli intrusi!", "." },
  ["306a9d1aef2aac21"] = { "Hai fatto tutto ciò che ti ho chiesto, {name}. Qui non c'è davvero più nulla per te. Se ti interessa proseguire la tua carriera come agente della ⟦Thorium Brotherhood=Fratellanza del Torio⟧, parla con ⟦Lokhtos Darkbargainer=Lokhtos Pattoscuro⟧ al Torvo Beone, nei ⟦Blackrock Depths=Sotterranei di Roccianera⟧.\n\nAddio!", "." },
  ["306f752b9a45897c"] = { "Questo però sbilancerà il fulcro magico e causerà una vibrazione inversa nell'etere.", "." },
  ["3073b91324537351"] = { "I generali ci dicono che abbiamo raccolto tutto ciò che ci serve per l'imminente Guerra di ⟦Ahn'Qiraj=Ahn'qiraj⟧. Ora stiamo solo aspettando che l'⟦Horde=Orda⟧ finisca di accumulare le sue scorte, poi potrà cominciare il trasporto del materiale bellico.", "." },
  ["307782b314cb192d"] = { "Ah, {race}, sei <tornato/tornata>!", "." },
  ["30874729a84a4832"] = { "Ho appena terminato un nuovo implosore dimensionale che mi riempirà d'oro oltre i miei più sfrenati sogni goblin! Mi basta solo trovare un abile esperto di ⟦Goblin Engineer=Ingegneria dei Goblin⟧ che costruisca uno squarciatore dimensionale da collegarci, e provarlo!", "." },
  ["308de040ccb06a19"] = { "Per mani esperte come le mie è un procedimento semplice.\n\nL'aspetto più difficile della creazione di oggetti con pelli e carapaci di bestie è procurarsi quelle parti. Ora, se potessi portarmi una pelle intatta di questa bestia, potrei ricavarne diversi oggetti potenti.", "." },
  ["30930e310a1d9f86"] = { "Le carte della ⟦Darkmoon Faire=Fiera di Lunacupa⟧? Per quelle rivolgiti al professore, qui. Vieni da me se commerci in antichità e manufatti difficili da trovare.", "." },
  ["3099c28e190bc25b"] = { "È la stagione dei grandi affari! Fa la la la la!", "." },
  ["30a1217e324f2317"] = { "Ciao Corbett! Ecco a te! Spero che gli affari vadano bene nella tua sartoria...?", "." },
  ["30a2781ff447c9a2"] = { "Eccomi finalmente a ⟦Lakeshire=Borgolago⟧: venite tutti, venite, e approfittate delle meravigliose offerte di Antonio Perelli.", "." },
  ["30a60c54f49f9495"] = { "Biglietti! Riscattate qui i vostri Darkmoon Faire Prize Ticket! Premi meravigliosi ed esotici vi aspettano!", "." },
  ["30aa73e67de71b16"] = { "Il Dio Antico creò avatar dai silitidi a propria immagine. Questi avatar sarebbero stati conosciuti come Qiraji. Senzienti e con uno scopo, i Qiraji diedero un nome al loro creatore: nacque ⟦C'Thun=C'thun⟧... Per molte migliaia di anni i Qiraji lavorarono febbrilmente per costruire un esercito capace di devastare il mondo che avrebbe tradito il loro dio. La grande città fortezza di ⟦Ahn'Qiraj=Ahn'qiraj⟧ fu creata per ospitare i loro eserciti crescenti e prepararsi alla venuta di ⟦C'Thun=C'thun⟧.", "." },
  ["30ab33241d3c3395"] = { "Chi controlla il Frostwolf Relief Hut?", "." },
  ["30ac246e0cd9f023"] = { "Michael Garrett, sull'anello superiore del ⟦Trade Quarter=Quartiere del Commercio⟧.", "." },
  ["30ba317dc6c873d2"] = { "Ah, Zaetar... <Celebras distoglie lo sguardo.>\n\nMio padre, Remulos, cercò di fermarlo...\n\nZaetar era testardo, e quando si innamorò di una principessa elementale della terra, mio padre seppe che la loro unione era maledetta, ma Zaetar si rifiutò di ascoltare.\n\nI centauri sono il frutto del suo errore. Nacquero deformi e pieni d'odio; mio zio Zaetar fu ucciso dalla sua stessa progenie...\n\nLa malvagia principessa, Theradras, custodisce ancora i suoi resti qui, nelle caverne di cristallo.", "." },
  ["30bd3a4ac5f86835"] = { "%s ingolla la sua bottiglia di veleno in preda alla disperazione!", "." },
  ["30beafe3a260638f"] = { "Che il tuo bicchiere, se è pieno, possa esserlo di nuovo!", "." },
  ["30bf357d03285dd4"] = { "Anche se gli scavi in queste rovine vanno a rilento, confido che non durerà a lungo. Nel frattempo, però, mi farebbe comodo qualcuno come te. Vorresti aiutare la Dwarven Explorers' Guild?", "." },
  ["30c07ac42b376c3f"] = { "Allontanati da lì!", "." },
  ["30c790c221e43965"] = { "%s sussulta mentre la sua pelle luccica.", "." },
  ["30d1fac4c4a49ae6"] = { "Ok, {name}, andiamo a cercare il posto dove ho lasciato quel fossile misterioso. Seguimi!", "." },
  ["30dde7fb62cb1fda"] = { "Muori! Muori!", "." },
  ["30de0d1a3d254b7f"] = { "Ho perso il mio ⟦Sickle of Unyielding Strength=Falcetto della Forza Inflessibile⟧. Puoi sostituirmelo?", "." },
  ["30e1e08b1452d336"] = { "%s scompare di nuovo nella palude.", "." },
  ["30eba4de48ff69c2"] = { "Ho creato il totem. Tu, {name}, devi purificare il pozzo.", "." },
  ["30ec2512246e2cc2"] = { "<Un/Una> <sarto/sarta>, eh? Molto bene. Cosa vorresti imparare, <sarto/sarta>?", "." },
  ["30fa78de67d1e06a"] = { "Raccontami di più sulla storia di Remulos e Zaetar.", "." },
})
